mapper.select:
SELECT ss.*, mp.point_name AS point_name, ea.asset_name AS asset_name, loc.location_name AS asset_location FROM spray_system ss LEFT JOIN equipment_monitor_point mp ON ss.monitor_point_id = mp.id LEFT JOIN equipment_assets ea ON ss.equipment_id = ea.asset_id LEFT JOIN equipment_location loc ON ss.location_id = loc.location_id WHERE 1 = 1
AND ea.asset_name LIKE CONCAT('%', #{data.assetName}, '%')
AND loc.location_name LIKE CONCAT('%', #{data.locationName}, '%')
AND ss.operation_type = #{data.operationType}
AND ss.operation_time >= #{data.startTime}
AND ss.operation_time <= #{data.endTime}
ORDER BY ss.operation_time DESC
